def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # Find the row containing the longest contiguous non-background motif.
    candidates = []
    for i, row in enumerate(grid):
        runs = []
        j = 0
        while j < w:
            if row[j] == bg:
                j += 1
                continue
            k = j
            while k < w and row[k] != bg:
                k += 1
            runs.append((k - j, j, row[j:k]))
            j = k
        if runs:
            candidates.append((max(x[0] for x in runs), i, max(runs)))
    _, seed_r, (_, _, motif) = max(candidates)
    anchor = len(motif) // 2
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if r == seed_r:
            continue
        for c, value in enumerate(row):
            if value != bg:
                start = c - anchor
                for k, color in enumerate(motif):
                    if 0 <= start + k < w:
                        out[r][start + k] = color
    return out

